fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    let dur: i32 = 120;
    let step: i32 = t % dur;
    let p: i32 = step * 256 / dur;
    let span: i32 = w - 60;
    let lin: i32 = p;
    let ein: i32 = p * p / 256;
    let inv: i32 = 256 - p;
    let eout: i32 = 256 - inv * inv / 256;
    host::display::clear(0x000000);
    host::display::draw_string(8, h / 4 - 24, "LINEAR", 0x808080, 1);
    host::display::fill_rect(10 + span * lin / 256, h / 4, 40, 24, 0xffffff);
    host::display::draw_string(8, h / 2 - 24, "EASE IN", 0x808080, 1);
    host::display::fill_rect(10 + span * ein / 256, h / 2, 40, 24, 0x00c0ff);
    host::display::draw_string(8, h * 3 / 4 - 24, "EASE OUT", 0x808080, 1);
    host::display::fill_rect(10 + span * eout / 256, h * 3 / 4, 40, 24, 0xffc000);
    host::display::present();
}
